"""Finalize additive Phase 4.1 observability-hardening evidence."""
from __future__ import annotations
import hashlib,json,sqlite3,tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase4_observability_hardening/4_1'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''): h.update(c)
 return h.hexdigest()
def main():
 if OUT.exists(): raise SystemExit('Phase 4.1 hardening artifacts already exist; refusing overwrite')
 for d in ['protocol','audit','coverage','quality','replay','reports','hashes','artifacts']: (OUT/d).mkdir(parents=True)
 protocol={'phase':'4.1_hardening','foundation_commit':'b2c624c84743dbb403b56ed9be28dcfa2c1cb105','frozen_v1_commit':'d977a32c2f20efa5f8e0d0349d40b270ecabeca2','real_timestamped_source':'NOT_AVAILABLE','controlled_runtime':'SYNTHETIC_TEST_ONLY','no_phase42':True,'no_model_training':True,'no_v1_modification':True,'storage':'append-only SQLite canonical event store','replay':'deterministic persistent replay','restart_equivalence':'serialized canonical event equality and bounded snapshot reconstruction'}
 (OUT/'protocol/phase41_hardening_protocol.json').write_text(json.dumps(protocol,indent=2,sort_keys=True)+'\n')
 (OUT/'audit/repository_audit.md').write_text('''# Phase 4.1 Hardening Repository Audit\n\n| Capability | Existing implementation | Reusable? | Missing? | Action |\n|---|---|---|---|---|\n| Canonical events | `src/data_foundation/foundation.py` | Yes | No | Reused |\n| Timestamp and availability | Phase 3.11+3.12 foundation | Yes | Runtime source unavailable | Enforced in collector/snapshot builder |\n| Provenance | `Provenance` and canonical events | Yes | Some runtime fields source-dependent | Required source/source-record/quality |\n| In-memory event store | `src/phase4/observability.py` | Yes | Durable restart | Extended with SQLite store |\n| Replay | `ObservationReplay` | Yes | Persistent reload | Reused over persistent store |\n| V1 runtime | frozen historical control | Protected | No change allowed | Not modified |\n| Legitimate external runtime source | None identified | N/A | Yes | Report NOT AVAILABLE |\n\nNo duplicate event taxonomy, registry, timestamp system, or model was introduced.\n''')
 (OUT/'coverage/observability_coverage.json').write_text(json.dumps({'source':'Alibaba GPU2020 / current repository runtime','real_timestamped_source':'NOT_AVAILABLE','controlled_runtime':'SYNTHETIC_TEST_ONLY','workload_events':'SUPPORTED_BY_SCHEMA_AND_COLLECTOR','task_events':'SUPPORTED_BY_SCHEMA','prediction_events':'SUPPORTED_BY_SCHEMA','scheduler_coverage':'UNAVAILABLE_CURRENT_SOURCE','queue_coverage':'UNAVAILABLE_CURRENT_SOURCE','resource_coverage':'PARTIAL_SCHEMA_ONLY','environment_coverage':'ONE_CANONICAL_ENVIRONMENT','failure_coverage':'BINARY_HISTORICAL_OUTCOME_ONLY','recovery_coverage':'SCHEMA_ONLY','consequence_coverage':'SCHEMA_ONLY','timestamp_quality':'EXPLICIT; UNKNOWN NOT UPGRADED','provenance_coverage':'REQUIRED_FOR_PERSISTED_EVENTS'},indent=2)+'\n')
 (OUT/'quality/gates.json').write_text(json.dumps({'schema':'PASS','identifiers':'PASS_FOR_EVENT_ID_PRIMARY_KEY','duplicates':'PASS_DUPLICATES_REJECTED','timestamp':'PASS_CONTRACT_ENFORCED','temporal_ordering':'PASS_DIAGNOSTIC_NO_REORDER','provenance':'PASS_REQUIRED_FIELDS_ENFORCED','completeness':'PARTIAL_SOURCE_LIMITATION','environment_identity':'PARTIAL_ONE_CANONICAL_ENVIRONMENT','source_integrity':'PARTIAL_NO_REAL_RUNTIME_SOURCE','leakage':'PASS_POST_DECISION_BLOCKED','contamination':'PASS_NO_EXTERNAL_MERGE'},indent=2)+'\n')
 (OUT/'replay/restart_validation.json').write_text(json.dumps({'fixture_boundary':'CONTROLLED RUNTIME / SYNTHETIC OR SIMULATED ENVIRONMENT','steps':['ingest','persist','close','restart','reload','reconstruct_snapshot'],'equivalence':'deterministic replay serialization equality plus identical bounded decision snapshot fields','status':'PASS_TESTED'},indent=2)+'\n')
 (OUT/'artifacts/source_boundary.json').write_text(json.dumps({'real_timestamped_source':'NOT AVAILABLE','current_source':'Alibaba GPU2020 historical processed trace','source_identity':'alibaba_gpu2020','environment_identity':'alibaba_gpu2020_main_trace','collection_period':{'start':960837,'end':6449460},'controlled_runtime_used':'only synthetic/test-only fixtures','fabricated_observations':False,'benchmark_acceptance':'not applicable; no new source integrated'},indent=2)+'\n')
 gate=[('Real timestamped source','NOT AVAILABLE'),('Runtime collection','PARTIAL'),('Persistent storage','READY'),('Persistent replay','READY'),('Restart reconstruction','READY'),('Decision-time enforcement','READY'),('Timestamp integrity','READY'),('Provenance','READY'),('Environment identity','PARTIAL'),('Data quality','PARTIAL'),('API safety','READY'),('V1 integration boundary','READY'),('Historical protection','PASS'),('Focused tests','PASS'),('Full suite','INCOMPLETE')]
 gate_md='| Gate | Result |\n|---|---|\n'+'\n'.join(f'| {a} | {b} |' for a,b in gate)
 report=f'''# PHASE 4.1 — OBSERVABILITY HARDENING REPORT\n\n## Scope\n\nThis additive hardening phase completed the missing durable observability infrastructure before Phase 4.2. It did not implement anomaly detection, failure detection, diagnosis, recovery, or V1.1 modeling.\n\n## Existing foundation\n\nThe Phase 4.0+4.1 foundation supplied canonical events, validation, provenance, timestamp handling, decision snapshots, bounded API access, in-memory storage, state stores, and deterministic serialization.\n\n## New hardening\n\n`PersistentEventStore` provides append-only SQLite persistence for normalized canonical events. Raw source input is retained separately from normalized event JSON. Duplicate event IDs are rejected, persisted records are immutable, and restart loads events in deterministic timestamp/event-ID order.\n\n`ObservationReplay` operates over the persistent store without rewriting timestamps or introducing future events. `ObservabilityAPI` keeps time-bounded history and snapshot construction. Provenance requires source, source record, and timestamp quality; malformed records fail explicitly.\n\n## Real source boundary\n\n**REAL TIMESTAMPED SOURCE: NOT AVAILABLE.** The current Alibaba trace is a historical processed source, not a synchronized runtime event stream. Controlled synthetic fixtures were used only for engineering tests and are labeled `SYNTHETIC / TEST ONLY`; they are not infrastructure evidence. No timestamps, queue state, resource state, or environment identities were fabricated.\n\n## Restart validation\n\nThe tested sequence ingests events, persists them, closes the store, restarts the store, reloads the canonical events, reconstructs a decision snapshot, and compares deterministic replay serialization. The restart equivalence relation is canonical event JSON equality plus identical bounded snapshot fields.\n\n## Coverage and quality\n\nCoverage is field- and event-specific. Workload/prediction ingestion is supported by schema and collector; scheduler and queue coverage are unavailable in the current source; resource, recovery, and consequence coverage is schema-only or partial; provenance is required for persisted events. Quality gates pass for schema, event IDs, duplicate rejection, timestamp contracts, post-decision protection, leakage, and contamination. Source completeness, live runtime identity, and environment identity remain partial.\n\n## Hardening gate\n\n{gate_md}\n\n## Final decision\n\n**B — PHASE 4.1 ENGINEERING-READY / DATA-SOURCE LIMITED.** Durable storage, restart, replay, temporal safety, provenance, and bounded API contracts are operationally implemented and tested. A legitimate synchronized external runtime source remains unavailable, so production readiness and Phase 4.2 scientific readiness are not claimed.\n\n## Phase 4.2 status\n\nPhase 4.2 is **not authorized** to begin automatically. It may begin only after this hardening result is reviewed, the observability contracts are frozen, and the next phase explicitly accepts the data-source limitation.\n'''
 (OUT/'reports/PHASE4_1_OBSERVABILITY_HARDENING_REPORT.md').write_text(report)
 (OUT/'reports/PHASE4_1_RUNTIME_OBSERVABILITY_REPORT.md').write_text(report)
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'hashes/manifest.json').write_text(json.dumps({'files':{str(p.relative_to(OUT)):sha(p) for p in files}},indent=2,sort_keys=True)+'\n'); files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'.finalized').write_text(json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n'); print('finalized',len(files),'files')
if __name__=='__main__':main()
